import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_gemm(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Tiled GEMM kernel using CUTE tensors for global memory addressing
// Block computes a BM x BN tile of C, with BK reduction step per iteration.
// Each thread computes a TM x TN sub-tile stored in registers.
constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 8;
constexpr int TM = 8;
constexpr int TN = 8;
// blockDim = (BN/TN, BM/TM) = (16, 16) -> 256 threads

__global__ void cute_gemm_kernel(
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K)
{
    __shared__ float sA[BM][BK];
    __shared__ float sB[BK][BN];

    // CUTE tensors describing the global matrices (row-major)
    Tensor gA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));
    Tensor gB = make_tensor(make_gmem_ptr(B), make_shape(K, N), make_stride(N, Int<1>{}));
    Tensor gC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{}));

    int tx = threadIdx.x; // 0..15 -> N sub-tile
    int ty = threadIdx.y; // 0..15 -> M sub-tile
    int bx = blockIdx.x;
    int by = blockIdx.y;

    int row0 = by * BM;
    int col0 = bx * BN;

    int tid = ty * (BN / TN) + tx; // 0..255
    const int NTHREADS = (BM / TM) * (BN / TN); // 256

    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            acc[i][j] = 0.f;
        }
    }

    for (int k0 = 0; k0 < K; k0 += BK) {
        // Load sA tile: BM x BK using vectorized float4 loads
        #pragma unroll
        for (int idx = tid; idx < (BM * BK) / 4; idx += NTHREADS) {
            int r = idx / (BK / 4);
            int c4 = idx % (BK / 4);
            int c = c4 * 4;
            int gr = row0 + r;
            int gc = k0 + c;
            float4 val;
            if (gr < M && gc + 3 < K) {
                val = *reinterpret_cast<const float4*>(&A[gr * K + gc]);
            } else {
                val.x = (gr < M && gc + 0 < K) ? A[gr * K + gc + 0] : 0.f;
                val.y = (gr < M && gc + 1 < K) ? A[gr * K + gc + 1] : 0.f;
                val.z = (gr < M && gc + 2 < K) ? A[gr * K + gc + 2] : 0.f;
                val.w = (gr < M && gc + 3 < K) ? A[gr * K + gc + 3] : 0.f;
            }
            sA[r][c + 0] = val.x;
            sA[r][c + 1] = val.y;
            sA[r][c + 2] = val.z;
            sA[r][c + 3] = val.w;
        }
        // Load sB tile: BK x BN using vectorized float4 loads
        #pragma unroll
        for (int idx = tid; idx < (BK * BN) / 4; idx += NTHREADS) {
            int r = idx / (BN / 4);
            int c4 = idx % (BN / 4);
            int c = c4 * 4;
            int gr = k0 + r;
            int gc = col0 + c;
            float4 val;
            if (gr < K && gc + 3 < N) {
                val = *reinterpret_cast<const float4*>(&B[gr * N + gc]);
            } else {
                val.x = (gr < K && gc + 0 < N) ? B[gr * N + gc + 0] : 0.f;
                val.y = (gr < K && gc + 1 < N) ? B[gr * N + gc + 1] : 0.f;
                val.z = (gr < K && gc + 2 < N) ? B[gr * N + gc + 2] : 0.f;
                val.w = (gr < K && gc + 3 < N) ? B[gr * N + gc + 3] : 0.f;
            }
            sB[r][c + 0] = val.x;
            sB[r][c + 1] = val.y;
            sB[r][c + 2] = val.z;
            sB[r][c + 3] = val.w;
        }
        __syncthreads();
        // Compute: register-blocked outer product over the BK reduction dim
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float a_reg[TM];
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                a_reg[i] = sA[ty * TM + i][kk];
            }
            float b_reg[TN];
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                b_reg[j] = sB[kk][tx * TN + j];
            }
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    acc[i][j] += a_reg[i] * b_reg[j];
                }
            }
        }
        __syncthreads();
    }

    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        int gr = row0 + ty * TM + i;
        if (gr >= M) continue;
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            int gc = col0 + tx * TN + j;
            if (gc < N) {
                gC(gr, gc) = acc[i][j];
            }
        }
    }
}

torch::Tensor cute_gemm(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");

    auto A_c = A.contiguous().to(torch::kFloat32);
    auto B_c = B.contiguous().to(torch::kFloat32);

    int M = (int)A_c.size(0);
    int K = (int)A_c.size(1);
    int N = (int)B_c.size(1);
    TORCH_CHECK((int)B_c.size(0) == K, "B.size(0) must equal A.size(1)");

    auto C = torch::empty({M, N}, A_c.options());

    dim3 block(BN / TN, BM / TM); // (16, 16)
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_gemm_kernel<<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE gemm launch failed");
    return C;
}
"""

cute_ext = load_inline(
    name="cute_gemm_tiled_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_gemm"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_gemm(A, B)

